import{c as e,a1 as t,V as n,j as l,g as a,n as p,o as h,m as d}from"./chunks/framework.BQhatpAZ.js";const b=JSON.parse('{"title":"格式概览","description":"通过具体示例了解 TOON 语法——对象、数组、头部、键折叠和引号规则。","frontmatter":{"description":"通过具体示例了解 TOON 语法——对象、数组、头部、键折叠和引号规则。"},"headers":[],"relativePath":"zh/guide/format-overview.md","filePath":"zh/guide/format-overview.md"}'),k={name:"zh/guide/format-overview.md"};function o(r,s,c,g,E,y){const i=t("CopyOrDownloadAsMarkdownButtons");return n(),l("div",null,[s[0]||(s[0]=a("div",{style:{display:"none"},hidden:"true","aria-hidden":"true"},"Are you an LLM? You can read better optimized documentation at /zh/guide/format-overview.md for this page in Markdown format",-1)),s[1]||(s[1]=a("h1",{id:"格式概览",tabindex:"-1"},[p("格式概览 "),a("a",{class:"header-anchor",href:"#格式概览","aria-label":'Permalink to "格式概览"'},"​")],-1)),h(i),s[2]||(s[2]=d(`<p>带有具体示例的 TOON 语法参考。相关入门介绍请参阅 <a href="/guide/getting-started.html">快速开始</a>。</p><h2 id="数据模型" tabindex="-1">数据模型 <a class="header-anchor" href="#数据模型" aria-label="Permalink to &quot;数据模型&quot;">​</a></h2><p>TOON 与 JSON 使用相同的方式对数据建模:</p><ul><li><strong>基本类型(Primitives)</strong>:字符串、数字、布尔值和 <code>null</code></li><li><strong>对象(Objects)</strong>:从字符串键到值的映射</li><li><strong>数组(Arrays)</strong>:值的有序序列</li></ul><h3 id="根形式" tabindex="-1">根形式 <a class="header-anchor" href="#根形式" aria-label="Permalink to &quot;根形式&quot;">​</a></h3><p>一个 TOON 文档可以表示不同的根形式:</p><ul><li><strong>根对象</strong>(最常见):字段出现在深度为 0 的位置,没有父键</li><li><strong>根数组</strong>:以深度 0 处的 <code>[N]:</code> 或 <code>[N]{fields}:</code> 开头</li><li><strong>根基本类型</strong>:单个基本类型值(字符串、数字、布尔值或 null)</li></ul><p>本文档中的大多数示例使用根对象,但该格式同等支持这三种形式(<a href="https://github.com/toon-format/spec/blob/main/SPEC.md#5-concrete-syntax-and-root-form" target="_blank" rel="noreferrer">规范第 5 节</a>)。</p><h2 id="对象" tabindex="-1">对象 <a class="header-anchor" href="#对象" aria-label="Permalink to &quot;对象&quot;">​</a></h2><h3 id="简单对象" tabindex="-1">简单对象 <a class="header-anchor" href="#简单对象" aria-label="Permalink to &quot;简单对象&quot;">​</a></h3><p>带有基本类型值的对象使用 <code>key: value</code> 语法,每行一个字段:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Ada</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">active</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>缩进代替了大括号。冒号后跟一个空格。</p><h3 id="嵌套对象" tabindex="-1">嵌套对象 <a class="header-anchor" href="#嵌套对象" aria-label="Permalink to &quot;嵌套对象&quot;">​</a></h3><p>嵌套对象增加一级缩进(默认:2 个空格):</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Ada</span></span></code></pre></div><p>当一个键以 <code>:</code> 结尾且同一行没有值时,它会打开一个嵌套对象。下一缩进层级的所有行都属于该对象。</p><h3 id="空对象" tabindex="-1">空对象 <a class="header-anchor" href="#空对象" aria-label="Permalink to &quot;空对象&quot;">​</a></h3><p>根级别的空对象会产生一个空文档(没有任何行)。嵌套的空对象则表示为单独的 <code>key:</code>,没有子内容。</p><h2 id="数组" tabindex="-1">数组 <a class="header-anchor" href="#数组" aria-label="Permalink to &quot;数组&quot;">​</a></h2><p>TOON 会检测数组结构,并选择最高效的表示方式。数组总是在方括号中声明其长度:<code>[N]</code>。</p><h3 id="基本类型数组-内联" tabindex="-1">基本类型数组(内联) <a class="header-anchor" href="#基本类型数组-内联" aria-label="Permalink to &quot;基本类型数组(内联)&quot;">​</a></h3><p>基本类型(字符串、数字、布尔值、null)的数组以内联形式呈现:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tags[3]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">admin,ops,dev</span></span></code></pre></div><p>分隔符(默认为逗号)用于分隔各个值。包含当前生效分隔符的字符串必须加引号。</p><h3 id="对象数组-表格化" tabindex="-1">对象数组(表格化) <a class="header-anchor" href="#对象数组-表格化" aria-label="Permalink to &quot;对象数组(表格化)&quot;">​</a></h3><p>当数组中的所有对象共享同一组基本类型值的键时,TOON 会使用表格化格式:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group--0HTF" id="tab-FCHdpFk" checked><label data-title="基础表格化" for="tab-FCHdpFk">基础表格化</label><input type="radio" name="group--0HTF" id="tab-5758wi4"><label data-title="值中包含空格" for="tab-5758wi4">值中包含空格</label></div><div class="blocks"><div class="language-yaml vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">items[2]{sku,qty,price}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  A1,2,9.99</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  B2,1,14.5</span></span></code></pre></div><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">users[2]{id,name,role}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  1,Alice Admin,admin</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  2,&quot;Bob Smith&quot;,user</span></span></code></pre></div></div></div><p>头部 <code>items[2]{sku,qty,price}:</code> 声明了:</p><ul><li><strong>数组长度</strong>:<code>[2]</code> 表示 2 行</li><li><strong>字段名</strong>:<code>{sku,qty,price}</code> 定义了各列</li><li><strong>生效分隔符</strong>:逗号(默认)</li></ul><p>每一行都按照字段列表相同的顺序包含各个值。值被编码为基本类型(字符串、数字、布尔值、null),并以分隔符隔开。</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>表格化格式要求所有对象具有完全相同的字段集合(键相同,但每个对象内的顺序可以不同)、仅包含基本类型的值(不能有嵌套数组/对象),并且每个对象至少有一个键——如果数组中包含一个空的 <code>{}</code> 元素,则会回退到下文所述的展开列表形式。</p></div><h3 id="混合与非一致数组" tabindex="-1">混合与非一致数组 <a class="header-anchor" href="#混合与非一致数组" aria-label="Permalink to &quot;混合与非一致数组&quot;">​</a></h3><p>不满足表格化条件的数组会使用带连字符标记的列表格式:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">items[3]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">text</span></span></code></pre></div><p>每个元素以 <code>- </code> 开头,缩进比父数组头部深一级。</p><h3 id="作为列表项的对象" tabindex="-1">作为列表项的对象 <a class="header-anchor" href="#作为列表项的对象" aria-label="Permalink to &quot;作为列表项的对象&quot;">​</a></h3><p>当数组元素是对象时,它会以列表项的形式出现:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">items[2]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">First</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Second</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    extra</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>当一个表格化数组是列表项对象的第一个字段时,表格化头部会出现在连字符所在的那一行,行数据缩进两级,其他字段缩进一级:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">items[1]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">users[2]{id,name}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      1,Ada</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      2,Bob</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">active</span></span></code></pre></div><p>当对象只有一个表格化字段时,同样的模式也适用:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">items[1]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">users[2]{id,name}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      1,Ada</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      2,Bob</span></span></code></pre></div><p>这是&quot;第一个字段为表格化数组&quot;的列表项对象的规范编码方式。</p><h3 id="数组的数组" tabindex="-1">数组的数组 <a class="header-anchor" href="#数组的数组" aria-label="Permalink to &quot;数组的数组&quot;">​</a></h3><p>当你有一个包含基本类型内部数组的数组时:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">pairs[2]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1,2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3,4</span></span></code></pre></div><p>每个内部数组都在其列表项所在行拥有自己的头部。</p><p>当内部数组本身是对象数组或非一致数组时,同样的 <code>- [N]:</code> 头部会出现在连字符所在行,嵌套项紧随其后并再深一级缩进:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">items[3]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">summary</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Ada</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">draft</span></span></code></pre></div><h3 id="空数组" tabindex="-1">空数组 <a class="header-anchor" href="#空数组" aria-label="Permalink to &quot;空数组&quot;">​</a></h3><p>空数组对于字段渲染为 <code>key: []</code>,在根级别则渲染为 <code>[]</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">items</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span></code></pre></div><p>出于向后兼容考虑,旧式的 <code>items[0]:</code> 形式在解码时仍会被支持。</p><h2 id="数组头部" tabindex="-1">数组头部 <a class="header-anchor" href="#数组头部" aria-label="Permalink to &quot;数组头部&quot;">​</a></h2><h3 id="头部语法" tabindex="-1">头部语法 <a class="header-anchor" href="#头部语法" aria-label="Permalink to &quot;头部语法&quot;">​</a></h3><p>数组头部遵循以下模式:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>key[N&lt;delimiter?&gt;]&lt;{fields}&gt;:</span></span></code></pre></div><p>其中:</p><ul><li><strong>N</strong> 是非负整数长度</li><li><strong>delimiter</strong>(可选)显式声明生效的分隔符: <ul><li>不填 → 逗号(<code>,</code>)</li><li><code>\\t</code>(制表符)→ 制表符分隔</li><li><code>|</code> → 竖线分隔</li></ul></li><li><strong>fields</strong>(可选,用于表格化数组):<code>{field1,field2,field3}</code></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>数组长度 <code>[N]</code> 有助于 LLM 校验结构。如果你要求模型生成 TOON 输出,显式的长度声明能让你检测出内容是否被截断或格式错误。</p></div><h3 id="分隔符选项" tabindex="-1">分隔符选项 <a class="header-anchor" href="#分隔符选项" aria-label="Permalink to &quot;分隔符选项&quot;">​</a></h3><p>TOON 支持三种分隔符:逗号(默认)、制表符和竖线。分隔符的作用范围仅限于声明它的那个数组头部。</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-AvhE8" id="tab-LLfw5aW" checked><label data-title="逗号(默认)" for="tab-LLfw5aW">逗号(默认)</label><input type="radio" name="group-AvhE8" id="tab-9oAAVr9"><label data-title="制表符" for="tab-9oAAVr9">制表符</label><input type="radio" name="group-AvhE8" id="tab-ofWzh-e"><label data-title="竖线" for="tab-ofWzh-e">竖线</label></div><div class="blocks"><div class="language-yaml vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">items[2]{sku,name,qty,price}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  A1,Widget,2,9.99</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  B2,Gadget,1,14.5</span></span></code></pre></div><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">items[2	]{sku	name	qty	price}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  A1	Widget	2	9.99</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  B2	Gadget	1	14.5</span></span></code></pre></div><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">items[2|]{sku|name|qty|price}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  A1|Widget|2|9.99</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  B2|Gadget|1|14.5</span></span></code></pre></div></div></div><p>制表符和竖线分隔符会显式编码在头部的方括号和字段大括号中。在某个数组的作用范围内,只有生效的分隔符会触发引号处理——其他字符则作为字面数据。对象字段的值(<code>key: value</code>)遵循文档级分隔符(§11.1),而不受周围任何数组生效分隔符的影响。</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>制表符分隔通常比逗号分隔更高效地进行 token 化,尤其是在引号字符串较少的数据中。使用 <code>encode(data, { delimiter: &#39;\\t&#39; })</code> 可以进一步节省 token。</p></div><h2 id="键折叠-可选" tabindex="-1">键折叠(可选) <a class="header-anchor" href="#键折叠-可选" aria-label="Permalink to &quot;键折叠(可选)&quot;">​</a></h2><p>键折叠是一项可选的编码器特性(自规范 v1.5 起提供),它会将单键对象组成的链条折叠为以点分隔的路径,从而为深度嵌套的数据减少 token 消耗。</p><h3 id="基础折叠" tabindex="-1">基础折叠 <a class="header-anchor" href="#基础折叠" aria-label="Permalink to &quot;基础折叠&quot;">​</a></h3><p>标准嵌套:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  metadata</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    items[2]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">a,b</span></span></code></pre></div><p>启用键折叠后(<code>keyFolding: &#39;safe&#39;</code>):</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">data.metadata.items[2]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">a,b</span></span></code></pre></div><p>三个嵌套对象被折叠为一个以点分隔的键 <code>data.metadata.items</code>。</p><h3 id="折叠适用的条件" tabindex="-1">折叠适用的条件 <a class="header-anchor" href="#折叠适用的条件" aria-label="Permalink to &quot;折叠适用的条件&quot;">​</a></h3><p>一条对象链在满足以下条件时可以被折叠:</p><ul><li>链中的每个对象都恰好只有一个键(指向下一个对象或一个叶子值)</li><li>叶子值是基本类型、数组或空对象</li><li>所有片段都是合法的标识符片段(仅限字母、数字、下划线;片段内不能有点号)</li><li>折叠后得到的键不会与已有的键发生冲突</li></ul><details class="details custom-block"><summary>高级折叠规则</summary><p><strong>片段要求(safe 模式):</strong></p><ul><li>所有被折叠的片段都必须匹配 <code>^[A-Za-z_][A-Za-z0-9_]*$</code>(不能包含点、连字符或其他特殊字符)</li><li>任何片段都不得需要按规范 §7.3 加引号</li><li>折叠后得到的键不得与同一深度下任何已有的同级字面键相同(避免冲突)</li></ul><p><strong>深度限制:</strong></p><ul><li><code>flattenDepth</code> 选项(默认:<code>Infinity</code>)控制要折叠多少个片段</li><li><code>flattenDepth: 2</code> 只折叠两段的链:<code>{a: {b: val}}</code> → <code>a.b: val</code></li><li>小于 2 的值没有实际效果</li></ul><p><strong>通过路径展开实现往返转换:</strong> 若要在解码时还原原始结构,请使用 <code>expandPaths: &#39;safe&#39;</code>。这会依据相同的安全规则,将带点号的键重新拆分为嵌套对象(<a href="https://github.com/toon-format/spec/blob/main/SPEC.md#134-key-folding-and-path-expansion" target="_blank" rel="noreferrer">规范 §13.4</a>)。</p></details><h3 id="通过路径展开实现往返转换" tabindex="-1">通过路径展开实现往返转换 <a class="header-anchor" href="#通过路径展开实现往返转换" aria-label="Permalink to &quot;通过路径展开实现往返转换&quot;">​</a></h3><p>在解码使用了键折叠的 TOON 时,启用路径展开以恢复嵌套结构:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { decode, encode } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@toon-format/toon&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> original</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { data: { metadata: { items: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;a&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;b&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] } } }</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 使用折叠进行编码</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> toon</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> encode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(original, { keyFolding: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;safe&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// → &quot;data.metadata.items[2]: a,b&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 使用展开进行解码</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> restored</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> decode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(toon, { expandPaths: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;safe&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// → { data: { metadata: { items: [&#39;a&#39;, &#39;b&#39;] } } }</span></span></code></pre></div><p>路径展开默认关闭,因此带点号的键在未显式启用该选项时会被视为字面键处理。</p><h2 id="引号与类型" tabindex="-1">引号与类型 <a class="header-anchor" href="#引号与类型" aria-label="Permalink to &quot;引号与类型&quot;">​</a></h2><h3 id="字符串何时需要加引号" tabindex="-1">字符串何时需要加引号 <a class="header-anchor" href="#字符串何时需要加引号" aria-label="Permalink to &quot;字符串何时需要加引号&quot;">​</a></h3><p>TOON <strong>只在必要时</strong>才为字符串加引号,以最大化 token 效率。以下情况字符串必须加引号:</p><ul><li>空字符串(<code>&quot;&quot;</code>)</li><li>存在开头或结尾的空白字符</li><li>值等于 <code>true</code>、<code>false</code> 或 <code>null</code>(区分大小写)</li><li>看起来像数字(例如 <code>&quot;42&quot;</code>、<code>&quot;-3.14&quot;</code>、<code>&quot;1e-6&quot;</code>、<code>&quot;05&quot;</code>)</li><li>包含特殊字符:冒号(<code>:</code>)、引号(<code>&quot;</code>)、反斜杠(<code>\\</code>)、方括号、花括号,或 U+0000–U+001F 范围内的任何控制字符</li><li>包含相关的分隔符(数组作用范围内为生效分隔符,其他情况下为文档级分隔符)</li><li>值等于 <code>&quot;-&quot;</code>,或以 <code>&quot;-&quot;</code> 开头且后面还有其他字符</li></ul><p>除此之外,字符串都可以不加引号。Unicode、emoji,以及内部(非开头/结尾)带空格的字符串都可以安全地不加引号:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Hello 世界 👋</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">note</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">This has inner spaces</span></span></code></pre></div><h3 id="转义序列" tabindex="-1">转义序列 <a class="header-anchor" href="#转义序列" aria-label="Permalink to &quot;转义序列&quot;">​</a></h3><p>在带引号的字符串和键中,共有六种合法的转义序列:</p><table tabindex="0"><thead><tr><th>字符</th><th>转义</th></tr></thead><tbody><tr><td>反斜杠(<code>\\</code>)</td><td><code>\\\\</code></td></tr><tr><td>双引号(<code>&quot;</code>)</td><td><code>\\&quot;</code></td></tr><tr><td>换行符(U+000A)</td><td><code>\\n</code></td></tr><tr><td>回车符(U+000D)</td><td><code>\\r</code></td></tr><tr><td>制表符(U+0009)</td><td><code>\\t</code></td></tr><tr><td>其他任意 U+0000–U+001F 控制字符</td><td><code>\\uXXXX</code></td></tr></tbody></table><p>其他转义方式(例如 <code>\\x</code>、<code>\\0</code>、<code>\\b</code>)一律会被拒绝,单独出现的代理项 <code>\\uXXXX</code> 值(U+D800–U+DFFF)同样会被拒绝。</p><h3 id="类型转换" tabindex="-1">类型转换 <a class="header-anchor" href="#类型转换" aria-label="Permalink to &quot;类型转换&quot;">​</a></h3><p>对于位于 §2 特例范围内的数值,会以规范的十进制形式输出;超出该范围时允许使用指数记法。非 JSON 类型(<code>NaN</code>、<code>Infinity</code>、<code>BigInt</code>、<code>Date</code>、<code>Set</code>、<code>Map</code>、<code>undefined</code> 等)在编码前会被归一化——完整的映射关系请参阅 <a href="/reference/api.html#type-normalization">API 参考——类型归一化</a>。</p><p>解码器在输入时同时接受十进制和指数形式(例如 <code>42</code>、<code>-3.14</code>、<code>1e-6</code>),并将带有禁止性前导零的 token(例如 <code>&quot;05&quot;</code>)视为字符串而非数字。</p><h3 id="使用-tojson-进行自定义序列化" tabindex="-1">使用 toJSON 进行自定义序列化 <a class="header-anchor" href="#使用-tojson-进行自定义序列化" aria-label="Permalink to &quot;使用 toJSON 进行自定义序列化&quot;">​</a></h3><p>拥有 <code>toJSON()</code> 方法的对象会通过调用该方法并在编码前对其结果进行归一化来完成序列化,这与 <code>JSON.stringify</code> 的行为类似:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> obj</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  data: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;example&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  toJSON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { info: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.data }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">encode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(obj)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// info: example</span></span></code></pre></div><p><code>toJSON()</code> 方法:</p><ul><li>优先于内置的归一化处理(Date、Array、Set、Map)</li><li>其结果会被递归地归一化</li><li>会在对象原型链中存在 <code>toJSON</code> 时被调用</li></ul><hr><p>关于引号、转义、类型转换以及严格模式解码的完整规则,请参阅 <a href="https://github.com/toon-format/spec/blob/main/SPEC.md" target="_blank" rel="noreferrer">规范 §2–4(数据模型)、§7(字符串与键)以及 §14(严格模式)</a>。</p>`,102))])}const m=e(k,[["render",o]]);export{b as __pageData,m as default};
